def login_required(roles=None):
    """roles=None means any logged-in account; roles=['researcher'] etc.
    restricts to specific role(s). Residents/TV never use this."""
    def decorator(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            if "username" not in session or "role" not in session:
                return redirect(url_for("login", next=request.path))
            if roles and session["role"] not in roles:
                return "Forbidden — your account (" + session["role"] + ") doesn't have access to this page.", 403
            return f(*args, **kwargs)
        return wrapped
    return decorator

