# ==============================================================================
# HISTORICAL REPORT — grid-aligned daily log, downloadable as CSV.
#
# Unlike telemetry_buffer above (which just appends one row per poll, every
# ~3 seconds, with no fixed spacing), this keeps ONE row per node per
# 5-minute wall-clock boundary (10:00, 10:05, 10:10, ...), starting from
# whenever this feature first runs. 5 minutes is the finest interval the
# History dropdown offers, and every other choice (10m/30m/1h) is an exact
# multiple of it, so filtering these rows by "is this timestamp's minute a
# multiple of the chosen interval" always lands exactly on the grid the
# person picked (10:00/10:10/10:20 for 10 min — never 10:03/10:08). Nothing
# is interpolated or guessed for a boundary that's skipped.
#
# CRITICAL — persistence caveat: daily_history (in memory) and the CSV
# backup under HISTORY_LOG_DIR only survive for as long as THIS process
# keeps running on the same machine. That's fine for an always-on single
# server, which is the current deployment. But on Vercel specifically,
# serverless functions can spin up a fresh container (fresh memory AND a
# fresh, empty filesystem) at any time — a cold start silently loses
# both copies. If/when this moves to Vercel for real, swap this for an
# external store (Vercel KV/Postgres/etc.) instead of trusting local
# memory or disk to survive.
# ==============================================================================
HISTORY_LOG_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "history_logs")
try:
    os.makedirs(HISTORY_LOG_DIR, exist_ok=True)
except OSError:
    pass  # read-only filesystem (e.g. some serverless hosts) — in-memory copy still works for this run

HISTORY_CSV_FIELDS = ["timestamp", "node", "node_label", "water_level_m", "water_flow_lmin",
                       "humidity_pct", "temperature_c", "tier", "rain_mm_hr"]
SAMPLE_GRID_SECONDS = 300  # 5 minutes — the finest interval HISTORY_INTERVALS (defined below) offers;
                           # every other option there (10m/30m/1h) is an exact multiple of this.

daily_history = {}                     # {"YYYY-MM-DD": [row, row, ...]} — today's data lives here first
_last_sample_boundary = {"ts": None}   # last 5-min grid boundary (epoch seconds) already recorded, so
                                        # repeated polls inside the same 5-min window don't double-write

def _history_log_path(day_key):
    safe_day = "".join(ch for ch in day_key if ch.isalnum() or ch == "-")
    return os.path.join(HISTORY_LOG_DIR, "history_" + safe_day + ".csv")

def _append_history_rows_to_disk(day_key, rows):
    path = _history_log_path(day_key)
    try:
        file_exists = os.path.exists(path)
        with open(path, "a", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=HISTORY_CSV_FIELDS)
            if not file_exists:
                writer.writeheader()
            for row in rows:
                writer.writerow({k: row.get(k, "") for k in HISTORY_CSV_FIELDS})
    except OSError:
        pass  # disk not writable this run — the in-memory copy in daily_history still works

def _load_history_rows_for_day(day_key):
    """In-memory copy wins (it's always current for today); falls back to
    the on-disk backup, e.g. after a restart earlier the same day."""
    if day_key in daily_history:
        return daily_history[day_key]
    path = _history_log_path(day_key)
    if os.path.exists(path):
        try:
            with open(path, "r", newline="", encoding="utf-8") as f:
                return list(csv.DictReader(f))
        except OSError:
            pass
    return []

def record_history_sample_if_due():
    """Called on every /api/status poll (~every 3s while a dashboard tab is
    open). The moment wall-clock time crosses into a new 5-minute grid
    boundary, records exactly one reading per node (+ the rain gauge) for
    that boundary — no more, no less, even if this fires several times
    inside the same 5-minute window."""
    now_ts = datetime.now().timestamp()
    boundary = int(now_ts // SAMPLE_GRID_SECONDS) * SAMPLE_GRID_SECONDS
    if _last_sample_boundary["ts"] == boundary:
        return
    _last_sample_boundary["ts"] = boundary

    boundary_dt = datetime.fromtimestamp(boundary)
    day_key = boundary_dt.strftime("%Y-%m-%d")
    ts_label = boundary_dt.strftime("%Y-%m-%d %H:%M:%S")

    new_rows = []
    for nid in NODE_ORDER:
        s = synth_reading(nid)
        new_rows.append({
            "timestamp": ts_label, "node": nid, "node_label": NODE_META[nid]["label"],
            "water_level_m": s["water_level"], "water_flow_lmin": s["water_flow"],
            "humidity_pct": s["humidity"], "temperature_c": s["temperature"], "tier": s["tier"],
            "rain_mm_hr": "",
        })
    r = synth_rain()
    new_rows.append({
        "timestamp": ts_label, "node": "node3", "node_label": "Barangay Hall (Rain Gauge)",
        "water_level_m": "", "water_flow_lmin": "", "humidity_pct": "", "temperature_c": "",
        "tier": "", "rain_mm_hr": r["intensity"],
    })

    daily_history.setdefault(day_key, []).extend(new_rows)
    _append_history_rows_to_disk(day_key, new_rows)

def history_report_rows(day_key, interval_seconds, node_filter="all"):
    """Rows for day_key, filtered to the chosen interval's grid and
    (optionally) a single node — the same filtering logic the CSV download
    and any future preview would both use."""
    interval_minutes = max(1, interval_seconds // 60)
    out = []
    for row in _load_history_rows_for_day(day_key):
        try:
            row_dt = datetime.strptime(row["timestamp"], "%Y-%m-%d %H:%M:%S")
        except (KeyError, ValueError):
            continue
        if row_dt.minute % interval_minutes != 0:
            continue
        if node_filter != "all" and row.get("node") != node_filter:
            continue
        out.append(row)
    return out

def log_event(level, msg):
    event_log.append({"ts": datetime.now().strftime("%H:%M:%S"), "level": level, "msg": msg})
    if len(event_log) > 300:
        del event_log[0]

def risk_tier(level):
    if level >= TIER_THRESHOLDS["red"]:
        return "red"
    if level >= TIER_THRESHOLDS["orange"]:
        return "orange"
    if level >= TIER_THRESHOLDS["yellow"]:
        return "yellow"
    return "none"

NODE_SEED = {"node1": 1, "node2": 13}

def synth_reading(node_id, tick_offset=0):
    """Deterministic pseudo-live reading from a smooth wave over time, kept
    within whichever tier band is currently forced for this node (via
    presenter controls) — no persistent thread needed, which matters since
    this runs as a stateless Vercel function as well as locally.

    Besides water_level (used to derive the risk tier), this also
    synthesizes the other three MAIN sensor parameters this thesis
    tracks per node — water_flow, humidity, and temperature — each on
    its own independent wave/phase so they don't just mirror the water
    level. Swap these three for real ESP32 sensor reads once wired in;
    keep the same dict keys so nothing downstream (API payload, both
    dashboards) needs to change.
    """
    seed = NODE_SEED[node_id]
    t = (datetime.now().timestamp() / 3.0) - tick_offset + seed
    wobble = (math.sin(t * 0.6) + 1) / 2  # 0..1
    tier = _forced_tier[node_id]
    ranges = {"none": (0.1, 0.4), "yellow": (0.5, 0.9), "orange": (1.0, 1.7), "red": (1.8, 2.5)}
    lo, hi = ranges[tier]
    level = round(lo + wobble * (hi - lo), 2)

    # Water flow (L/min) — rises with the same general trend as the water
    # level (more flow during higher tiers) but on its own phase offset.
    flow_wobble = (math.sin(t * 0.6 + 1.1) + 1) / 2
    flow_lo, flow_hi = (5, 30) if tier in ("none", "yellow") else (25, 75)
    water_flow = round(flow_lo + flow_wobble * (flow_hi - flow_lo), 1)

    # Ambient humidity (%RH) — independent slower wave.
    hum_wobble = (math.sin(t * 0.35 + 2.4) + 1) / 2
    humidity = round(55 + hum_wobble * 40, 1)

    # Ambient temperature (°C) — independent slower wave.
    temp_wobble = (math.sin(t * 0.22 + 0.7) + 1) / 2
    temperature = round(24 + temp_wobble * 7, 1)

    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return {
        "water_level": level,
        "water_flow": water_flow,
        "humidity": humidity,
        "temperature": temperature,
        "tier": risk_tier(level),
        "timestamp": now,
    }

def node_history(node_id):
    readings = [synth_reading(node_id, tick_offset=i) for i in range(HISTORY_LEN-1, -1, -1)]
    return {
        "water_level": [r["water_level"] for r in readings],
        "water_flow": [r["water_flow"] for r in readings],
        "humidity": [r["humidity"] for r in readings],
        "temperature": [r["temperature"] for r in readings],
    }

def node_history_times_fmt(node_id):
    now = datetime.now()
    return [(now - timedelta(seconds=i*3)).strftime("%H:%M:%S") for i in range(HISTORY_LEN-1, -1, -1)]

# ------------------------------------------------------------------------------
# HISTORY PANEL — selectable interval (5 min / 10 min / 30 min / 1 hour)
# ------------------------------------------------------------------------------
# node_history()/node_history_times_fmt() above feed the fast "Real-time
# Trends" sparkline (ticks every ~3s, matching the live poll) — that stays
# as-is on purpose, it's meant to look live.
#
# The separate History TABLE is what barangay staff actually read off the
# screen, so it needs readable, clock-friendly spacing instead of readings
# that are seconds apart. node_history_slow() below samples a much slower
# wave (keyed to real wall-clock time, not the fast live-tick wave) at
# whichever interval the user picks, so the 12 rows still look like a
# smooth, physically plausible trend at any zoom level instead of aliased
# noise from sampling the fast wave too sparsely.
HISTORY_INTERVALS = {"5m": 300, "10m": 600, "30m": 1800, "1h": 3600}
DEFAULT_HISTORY_INTERVAL_SECONDS = HISTORY_INTERVALS["10m"]

def node_history_slow(node_id, interval_seconds, count=HISTORY_LEN):
    seed = NODE_SEED[node_id]
    tier = _forced_tier[node_id]
    ranges = {"none": (0.1, 0.4), "yellow": (0.5, 0.9), "orange": (1.0, 1.7), "red": (1.8, 2.5)}
    lo, hi = ranges[tier]
    flow_lo, flow_hi = (5, 30) if tier in ("none", "yellow") else (25, 75)
    now = datetime.now().timestamp()
    fmt = "%H:%M" if interval_seconds < 3600 else "%b %d, %H:%M"

    water_level, water_flow, humidity, temperature, times = [], [], [], [], []
    for i in range(count - 1, -1, -1):
        t = now - i * interval_seconds
        wobble = (math.sin(t / 2400.0 + seed) + 1) / 2
        flow_wobble = (math.sin(t / 2400.0 + seed + 1.1) + 1) / 2
        hum_wobble = (math.sin(t / 5400.0 + seed + 2.4) + 1) / 2
        temp_wobble = (math.sin(t / 8100.0 + seed + 0.7) + 1) / 2
        water_level.append(round(lo + wobble * (hi - lo), 2))
        water_flow.append(round(flow_lo + flow_wobble * (flow_hi - flow_lo), 1))
        humidity.append(round(55 + hum_wobble * 40, 1))
        temperature.append(round(24 + temp_wobble * 7, 1))
        times.append(datetime.fromtimestamp(t).strftime(fmt))

    return {
        "water_level": water_level,
        "water_flow": water_flow,
        "humidity": humidity,
        "temperature": temperature,
        "times": times,
        "tier": risk_tier(water_level[-1]) if water_level else "none",
    }

def eta_minutes_to_red(node_id):
    """Rule-based placeholder for the edge-AI classifier's own prediction —
    extrapolates from this node's OWN recent trend only. Swap for your
    trained model's output; keep node isolation intact when you do."""
    levels = node_history(node_id)["water_level"]
    if len(levels) < 4:
        return None
    recent = levels[-4:]
    diffs = [recent[i+1] - recent[i] for i in range(len(recent)-1)]
    avg_rate = sum(diffs) / len(diffs)
    current = levels[-1]
    threshold = TIER_THRESHOLDS["red"]
    if current >= threshold:
        return 0
    if avg_rate <= 0.001:
        return None
    remaining = threshold - current
    seconds_needed = (remaining / avg_rate) * 3
    return round(seconds_needed / 60, 1)

def ai_confidence_for(tier):
    """Placeholder for the trained edge-AI classifier's own reported
    confidence. Steady-state/fully-flooded reads as decisive; the
    transitional bands (Yellow/Orange) are inherently more uncertain."""
    seed = (int(datetime.now().timestamp()) // 3) % 100
    if tier in ("none", "red"):
        return round(87 + (seed % 12), 1)
    return round(58 + (seed % 23), 1)

def current_node_status():
    return {nid: synth_reading(nid) for nid in NODE_ORDER}

def synth_hw(dev_id):
    """Hardware health, honoring forced overrides for demoing fault
    conditions. ESP nodes are synthetic (no real telemetry link exists
    yet) — computed per request, no background thread needed. The Pi Hub
    uses REAL psutil measurements of whatever machine is running this
    Flask process, since in the actual deployment that IS the Pi."""
    dev = dict(HARDWARE[dev_id])
    forced = _forced_hw[dev_id]
    t = datetime.now().timestamp() / 5.0
    wobble = (math.sin(t + hash(dev_id) % 7) + 1) / 2
    dev["status"] = forced if forced else "online"
    if dev["kind"] == "esp":
        dev["battery_pct"] = round(max(4.0, dev["battery_pct"] - wobble * 2), 1)
        dev["latency_ms"] = round(20 + wobble * 40, 1)
    else:
        try:
            import psutil
            dev["cpu_pct"] = psutil.cpu_percent(interval=0.0)
            dev["mem_pct"] = psutil.virtual_memory().percent
        except ImportError:
            dev["cpu_pct"] = round(20 + wobble * 40, 1)
            dev["mem_pct"] = round(35 + wobble * 30, 1)
        dev["latency_ms"] = round(1 + wobble * 3, 1)
    dev["last_heartbeat"] = datetime.now().strftime("%H:%M:%S") if dev["status"] != "offline" else "—"
    return dev

def current_hardware():
    return {dev_id: synth_hw(dev_id) for dev_id in HARDWARE}

def synth_rain():
    t = datetime.now().timestamp() / 7.0
    wobble = (math.sin(t) + 1) / 2
    intensity = round(wobble * 22, 1)
    return {"intensity": intensity, "today_total": round(intensity * 3.2, 1),
            "timestamp": datetime.now().strftime("%H:%M:%S")}

def rain_label(intensity):
    if intensity <= 0.1:
        return "No rain right now"
    if intensity < 5:
        return "Light rain falling"
    if intensity < 15:
        return "Moderate rain falling"
    return "Heavy rain falling now"

def rain_history():
    return [round(((math.sin((datetime.now().timestamp()/7.0) - i) + 1) / 2) * 22, 1) for i in range(HISTORY_LEN-1, -1, -1)]

def track_transitions_and_log():
    """Detects tier/hardware changes between polls and appends to the event
    log — the stateless equivalent of a background thread's continuous
    monitoring. Runs once per /api/status call."""
    for nid in NODE_ORDER:
        tier = risk_tier(synth_reading(nid)["water_level"])
        if tier != _last_tier_seen[nid]:
            sev = {"none": 0, "yellow": 1, "orange": 2, "red": 3}
            level = "WARN" if sev[tier] in (1, 2) else ("ERROR" if tier == "red" else "INFO")
            log_event(level, NODE_META[nid]["short"] + " tier changed: " + _last_tier_seen[nid] + " -> " + tier)
            _last_tier_seen[nid] = tier
    for dev_id in HARDWARE:
        status = synth_hw(dev_id)["status"]
        if status != _last_hw_seen[dev_id]:
            level = "ERROR" if status == "offline" else ("WARN" if status == "degraded" else "INFO")
            log_event(level, HARDWARE[dev_id]["label"] + " status changed: " + _last_hw_seen[dev_id] + " -> " + status)
            _last_hw_seen[dev_id] = status

def append_telemetry_row():
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    for nid in NODE_ORDER:
        s = synth_reading(nid)
        telemetry_buffer.append({
            "timestamp": ts, "node": NODE_META[nid]["short"], "water_level_m": s["water_level"],
            "tier": s["tier"], "device": NODE_META[nid]["device"],
            "device_status": synth_hw(NODE_META[nid]["device"])["status"],
        })
    r = synth_rain()
    telemetry_buffer.append({
        "timestamp": ts, "node": "Node 3", "water_level_m": "", "tier": "",
        "rain_mm_hr": r["intensity"], "device": "esp3", "device_status": synth_hw("esp3")["status"],
    })
    if len(telemetry_buffer) > TELEMETRY_BUFFER_LEN:
        del telemetry_buffer[:len(telemetry_buffer) - TELEMETRY_BUFFER_LEN]

def compute_ai_prediction(nid):
    """Rule-based placeholder for this NODE's edge-AI flood prediction —
    deliberately not blended with the other node. Swap for your trained
    classifier's output; keep the same shape."""
    tier = risk_tier(synth_reading(nid)["water_level"])
    eta = eta_minutes_to_red(nid)
    label = NODE_META[nid]["label"]
    if tier == "red":
        narrative = "Flooding is happening now at " + label + "."
    elif eta is None:
        narrative = "Levels are steady at " + label + " — no significant rise predicted."
    elif eta < 1:
        narrative = "Levels at " + label + " are very close to flood stage — watch closely."
    else:
        narrative = "At this rate, flooding at " + label + " is expected in about " + str(round(eta)) + " minutes."
    score = {"none": 15, "yellow": 45, "orange": 70, "red": 90}[tier]
    return {"risk_score": score, "tier": tier, "narrative": narrative, "eta_minutes": eta}

