import json as _json

def build_api_payload():
    """Payload for the main dashboard (/) — per-node only, no aggregate."""
    status = current_node_status()
    tiers = {nid: status[nid]["tier"] for nid in NODE_ORDER}
    hist_out = {nid: node_history(nid) for nid in NODE_ORDER}
    hist_times_out = {nid: node_history_times_fmt(nid) for nid in NODE_ORDER}
    eta_out = {nid: eta_minutes_to_red(nid) for nid in NODE_ORDER}
    ai_conf = {nid: ai_confidence_for(tiers[nid]) for nid in NODE_ORDER}
    predictions = {nid: compute_ai_prediction(nid) for nid in NODE_ORDER}
    track_transitions_and_log()
    append_telemetry_row()
    record_history_sample_if_due()
    return {
        "status": status,
        "tier": tiers,
        "tier_color": TIER_COLOR,
        "history": hist_out,
        "history_times": hist_times_out,
        "eta": eta_out,
        "ai_confidence": ai_conf,
        "prediction": predictions,
        "hardware": current_hardware(),
        "snapshots": node_snapshots,
        "rain": {**synth_rain(), "label": rain_label(synth_rain()["intensity"])},
        "rain_history": rain_history(),
        "alerts": list(reversed(event_log[-6:])),
        "log": list(reversed(event_log[-60:])),
        # Lightweight — no image bytes — so the 3s poll stays cheap. The
        # dashboard compares reports_latest_id against the id it already
        # knows about and only fetches the one new report's image (via
        # /api/report/<id>) when this actually goes up.
        "reports_latest_id": resident_reports[-1]["id"] if resident_reports else 0,
        "reports_pending": sum(1 for r in resident_reports if r["status"] == "Pending"),
    }

@app.route('/')
def root():
    if "username" not in session:
        return redirect(url_for("login"))
    if session.get("role") == "researcher":
        return redirect(url_for("researcher_dashboard"))
    return redirect(url_for("barangay_dashboard"))

@app.route('/login', methods=['GET', 'POST'])
def login():
    error = None
    if request.method == 'POST':
        username = request.form.get('username', '')
        password = request.form.get('password', '')
        account = ACCOUNTS.get(username)
        if account and check_password_hash(account["password_hash"], password):
            session['username'] = username
            session['role'] = account["role"]
            session['display_name'] = account["display_name"]
            next_url = request.args.get('next')
            if account["role"] == "researcher":
                return redirect(next_url or url_for('researcher_dashboard'))
            return redirect(next_url or url_for('barangay_dashboard'))
        error = "Incorrect username or password."
    return render_template_string(LOGIN_HTML, error=error, logo_b64=LOGO_B64)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

def _dashboard_context():
    active = request.args.get('node', 'node1')
    if active not in NODE_ORDER:
        active = 'node1'
    status = current_node_status()
    tier_color_by_node = {nid: TIER_COLOR[status[nid]["tier"]] for nid in NODE_ORDER}
    rain_now = synth_rain()
    rain_now["label"] = rain_label(rain_now["intensity"])
    return dict(
        status=status,
        active=active,
        rain=rain_now,
        meta=ALL_META,
        hq=HQ_META,
        rain_meta=RAIN_META,
        node_order=NODE_ORDER,
        tabs=ALL_TABS,
        tier_color=tier_color_by_node,
        reports=resident_reports,
        alerts=list(reversed(event_log[-6:])),
        hardware=current_hardware(),
        meta_json=_json.dumps(ALL_META),
        logo_b64=LOGO_B64,
        display_name=session.get('display_name', ''),
        carto_api_key=CARTO_API_KEY,
    )

