@app.route('/api/node-history/<node_id>')
@login_required(roles=['official', 'researcher'])
def api_node_history(node_id):
    """Backs the History panel's interval dropdown (5 min / 10 min / 30 min
    / 1 hour) — separate from /api/status so the fast live poll doesn't
    keep overwriting it with second-apart readings."""
    if node_id not in NODE_ORDER:
        return jsonify({"error": "unknown node"}), 404
    try:
        interval_seconds = int(request.args.get('interval', DEFAULT_HISTORY_INTERVAL_SECONDS))
    except (TypeError, ValueError):
        interval_seconds = DEFAULT_HISTORY_INTERVAL_SECONDS
    if interval_seconds not in HISTORY_INTERVALS.values():
        interval_seconds = DEFAULT_HISTORY_INTERVAL_SECONDS
    return jsonify(node_history_slow(node_id, interval_seconds))

