@app.route('/api/snapshot/<node_id>', methods=['POST'])
@login_required(roles=['official', 'researcher'])
def request_snapshot(node_id):
    """Requests a fresh capture from that node's ESP32-S3 camera module.
    No physical camera is wired in yet — this records the request/ack
    cycle (timestamp + counter) so the UI and interaction pattern are
    ready for when real image upload lands. Wire the ESP32-S3's actual
    JPEG upload into this handler when the hardware is ready."""
    if node_id not in CAMERA_NODES:
        return jsonify({"ok": False, "error": "no camera on this node"}), 400
    node_snapshots[node_id]["last_captured"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    node_snapshots[node_id]["requested_count"] += 1
    log_event("INFO", "Snapshot requested from " + HARDWARE[NODE_META[node_id]["device"]]["label"])
    return jsonify({"ok": True, "node_id": node_id, "snapshot": node_snapshots[node_id]})

@app.route('/api/config/node/<node_id>', methods=['POST'])
@login_required(roles=['researcher'])
def update_node_config(node_id):
    if node_id not in NODE_META:
        return jsonify({"ok": False, "error": "unknown node_id"}), 400
    payload = request.get_json(silent=True) or {}
    if "label" in payload:
        NODE_META[node_id]["label"] = str(payload["label"])[:60]
    if "lat" in payload:
        NODE_META[node_id]["lat"] = float(payload["lat"])
    if "lng" in payload:
        NODE_META[node_id]["lng"] = float(payload["lng"])
    ALL_META[node_id] = NODE_META[node_id]
    return jsonify({"ok": True, "node": NODE_META[node_id]})

@app.route('/api/config/thresholds', methods=['POST'])
@login_required(roles=['researcher'])
def update_thresholds():
    payload = request.get_json(silent=True) or {}
    try:
        yellow = float(payload.get("yellow", TIER_THRESHOLDS["yellow"]))
        orange = float(payload.get("orange", TIER_THRESHOLDS["orange"]))
        red = float(payload.get("red", TIER_THRESHOLDS["red"]))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "yellow/orange/red must be numbers"}), 400
    if not (yellow < orange < red):
        return jsonify({"ok": False, "error": "thresholds must satisfy yellow < orange < red"}), 400
    TIER_THRESHOLDS["yellow"] = yellow
    TIER_THRESHOLDS["orange"] = orange
    TIER_THRESHOLDS["red"] = red
    return jsonify({"ok": True, "thresholds": TIER_THRESHOLDS})

@app.route('/api/export.csv')
@login_required(roles=['official', 'researcher'])
def export_csv():
    buf = io.StringIO()
    fieldnames = ["timestamp", "node", "water_level_m", "tier", "rain_mm_hr", "device", "device_status"]
    writer = csv.DictWriter(buf, fieldnames=fieldnames)
    writer.writeheader()
    for row in telemetry_buffer:
        writer.writerow({k: row.get(k, "") for k in fieldnames})
    log_event("INFO", "Telemetry CSV exported (" + str(len(telemetry_buffer)) + " rows).")
    return Response(buf.getvalue(), mimetype="text/csv",
                     headers={"Content-Disposition": "attachment; filename=apaw_telemetry.csv"})

@app.route('/api/history_report.csv')
@login_required(roles=['official', 'researcher'])
def history_report_csv():
    """Downloadable historical report — one row per node per grid-aligned
    timestamp, at whichever interval the History panel's dropdown is set
    to (5/10/30/60 min). Timestamps always land exactly on that grid
    (10:00, 10:10, 10:20, ... for 10 min — never 10:03, 10:08) because
    record_history_sample_if_due() above only ever writes rows on 5-minute
    boundaries, and every other interval is an exact multiple of 5."""
    node_filter = request.args.get('node', 'all')
    if node_filter not in ('all', *NODE_ORDER):
        node_filter = 'all'
    try:
        interval_seconds = int(request.args.get('interval', DEFAULT_HISTORY_INTERVAL_SECONDS))
    except (TypeError, ValueError):
        interval_seconds = DEFAULT_HISTORY_INTERVAL_SECONDS
    if interval_seconds not in HISTORY_INTERVALS.values():
        interval_seconds = DEFAULT_HISTORY_INTERVAL_SECONDS
    interval_minutes = interval_seconds // 60

    day_key = request.args.get('date', datetime.now().strftime("%Y-%m-%d"))
    rows = history_report_rows(day_key, interval_seconds, node_filter)

    buf = io.StringIO()
    writer = csv.DictWriter(buf, fieldnames=HISTORY_CSV_FIELDS)
    writer.writeheader()
    for row in rows:
        writer.writerow({k: row.get(k, "") for k in HISTORY_CSV_FIELDS})

    log_event("INFO", "Historical report CSV exported (" + str(len(rows)) + " rows, every " +
              str(interval_minutes) + " min, " + day_key +
              (", " + node_filter if node_filter != 'all' else ", all nodes") + ").")

    filename = "apaw_history_" + day_key + "_every" + str(interval_minutes) + "min" + \
               ("_" + node_filter if node_filter != 'all' else "") + ".csv"
    return Response(buf.getvalue(), mimetype="text/csv",
                     headers={"Content-Disposition": "attachment; filename=" + filename})

@app.route('/api/system')
@login_required(roles=['researcher'])
def system_stats():
    """Real host diagnostics. Also what the Raspberry Pi Hub hardware card
    uses for CPU/Memory in current_hardware() — one real measurement, not
    two disagreeing simulated numbers, when this literally runs ON the Pi."""
    stats = {"cpu_percent": None, "memory_percent": None, "memory_used_mb": None,
              "memory_total_mb": None, "disk_percent": None, "disk_free_gb": None,
              "telemetry_rows": len(telemetry_buffer),
              "note": "On Vercel this reflects the ephemeral function container, not physical Pi hardware. Run on the Pi itself for real numbers."}
    try:
        import psutil
        stats["cpu_percent"] = psutil.cpu_percent(interval=0.2)
        vm = psutil.virtual_memory()
        stats["memory_percent"] = vm.percent
        stats["memory_used_mb"] = round(vm.used / (1024 * 1024), 1)
        stats["memory_total_mb"] = round(vm.total / (1024 * 1024), 1)
    except ImportError:
        pass
    return jsonify(stats)

